<?php require_role('admin');$pageTitle='Monitoring Reports';$pageSubtitle='Actionable indicators for project coordination';$byStatus=db_all("SELECT status,COUNT(*) total FROM sessions GROUP BY status ORDER BY total DESC");$byMilestone=db_all("SELECT status,COUNT(*) total FROM milestones GROUP BY status ORDER BY total DESC");$atRisk=db_all("SELECT p.*,u.full_name student_name,s.full_name supervisor_name FROM projects p JOIN users u ON u.id=p.student_id LEFT JOIN users s ON s.id=p.supervisor_id ORDER BY p.id");$atRisk=array_values(array_filter($atRisk,fn($p)=>progress_for_project((int)$p['id'])<40));include __DIR__.'/../includes/layout_top.php'; ?>
<div class="split-grid"><section class="card"><div class="card-header"><div><h2>Session status distribution</h2><p>Operational supervision pipeline</p></div></div><?php foreach($byStatus as $r):?><div class="list-card"><div><h4><?= e(ucfirst($r['status'])) ?></h4><p>Session records</p></div><strong><?= (int)$r['total'] ?></strong></div><?php endforeach;?></section><section class="card"><div class="card-header"><div><h2>Milestone status distribution</h2><p>Academic deliverable pipeline</p></div></div><?php foreach($byMilestone as $r):?><div class="list-card"><div><h4><?= e(ucwords(str_replace('_',' ',$r['status']))) ?></h4><p>Milestone records</p></div><strong><?= (int)$r['total'] ?></strong></div><?php endforeach;?></section></div>
<div class="card"><div class="card-header"><div><h2>Students requiring attention</h2><p>Projects below 40% approved progress.</p></div><button class="button small secondary" onclick="window.print()">Print report</button></div><?php if(!$atRisk):?><div class="empty-state">No active project is currently below the attention threshold.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Student</th><th>Project</th><th>Supervisor</th><th>Progress</th><th>Recommended coordinator action</th></tr></thead><tbody><?php foreach($atRisk as $r):?><tr><td><strong><?= e($r['student_name']) ?></strong></td><td><?= e($r['title']) ?></td><td><?= e($r['supervisor_name']?:'Unassigned') ?></td><td><span class="badge danger"><?= progress_for_project((int)$r['id']) ?>%</span></td><td>Confirm recent supervision activity, review overdue milestones, and agree a recovery schedule.</td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php include __DIR__.'/../includes/layout_bottom.php'; ?>
